// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    address bank;

    function setUp() public {
        c = new EtherLotto();
        bank = c.bank();
    }

    function testFuzz_property(uint256 seed, uint256 numPlays) public {
        vm.warp(seed);
        numPlays = bound(numPlays, 1, 20);

        uint256 balanceBefore = address(c).balance;
        uint256 potBefore = c.pot();

        for (uint256 i = 0; i < numPlays; i++) {
            vm.deal(address(this), 10);
            c.play{value: 10}();
        }

        uint256 balanceAfter = address(c).balance;

        if (balanceAfter < balanceBefore) {
            uint256 spent = balanceBefore - balanceAfter;
            assertTrue(spent <= potBefore);
        } else {
            assertTrue(true);
        }
    }

    receive() external payable {}
}
